137	import org.springframework.web.bind.annotation.PathVariable;
138	import org.springframework.web.bind.annotation.RequestHeader;
139	
140	/**
141	 * Moves the claim to the status the action leads to; refuses a change its status does not allow. Opening gives
142	 * the claim the sheet's next number and records who opened it; a voided claim keeps its number (never reused). The one who opened a
143	 * claim cannot settle it, and a clerk (any name not made a steward) settles a claim only when its due is at or below
144	 * the sheet's clerk limit (a due of n/a is within any limit; no limit when the sheet has none). Settling fixes the claim's due at the rate of the grade its
145	 * person had on the claim's date, in force on the claim's date, at least the sheet's floor (or at the figure its person's last statement bound it to), plus its late charge on the sheet's today (none when no rate applies then, so it stays live). A claim dated in a closed period cannot change status. Returns the claim's number for the
146	 * audit.
147	 */
148	public class ApplyClaimStatus {
149	    public Integer apply(@PathVariable("action") String action, @Val Claim claim, ClaimRepository repository,
150	            EntityManager entityManager, PersonRepository people, RateRepository rates, PersonGradeRepository grades, PeriodRepository periods,
151	            @Val Sheet sheet, RoleRepository roles,
152	            @RequestHeader(name = "X-User", required = false) String userHeader) throws ClaimStatusException, ClerkLimitException {
153	        String user = AuditUser.decode(userHeader);
154	        if (periods.isClosedOn(claim.getSheetId(), claim.getDate())) {
155	            throw new ClaimStatusException("A claim in a closed period cannot change status.");
156	        }
157	        if ("open".equals(action) && claim.getStatus().after(action) != null) {
158	            // Take the number first: it locks the sheet, then re-read the claim so a concurrent open is seen.
159	            repository.takeNextNumber(claim.getSheetId());
160	            entityManager.refresh(claim);
161	            ClaimStatus next = check(claim, action);
162	            claim.setNumber(repository.lastNumber(claim.getSheetId()));
163	            claim.setStatus(next);
164	            claim.setOpenedBy(user);
165	        } else {
166	            ClaimStatus next = check(claim, action);
167	            if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
168	                throw new ClaimStatusException("The one who opened a claim cannot settle it.");
169	            }
170	            if (next == ClaimStatus.SETTLED) {
171	                BigDecimal due = people.findById(claim.getPersonId())
172	                        .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
173	                                grades.gradesOf(p), sheet).due(claim))
174	                        .orElse(null);
175	                BigDecimal limit = sheet.getClerkLimit();
176	                if (limit != null && due != null && due.compareTo(limit) > 0
177	                        && !Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
178	                    throw new ClerkLimitException("A clerk cannot settle a claim whose due is above the clerk limit.");
179	                }
180	                claim.setDue(due);
181	            }
182	            claim.setStatus(next);
183	        }
184	        repository.saveAndFlush(claim);
185	        return claim.getNumber();
186	    }
187	
188	    private static ClaimStatus check(Claim claim, String action) throws ClaimStatusException {
189	        ClaimStatus next = claim.getStatus().after(action);
190	        if (next == null) {
191	            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot " + action + ".");
192	        }
193	        return next;
194	    }
195	}
