335	     *  @param grades the person's grades over time.
336	     *  @param sheet the sheet: its floor (a live due is at least it), and its late percent, terms and today (the
337	     *  late charge). */
338	    public ClaimFigures(List<Rate> rates, PersonGrades grades, Sheet sheet) {
339	        this.rates = rates;
340	        this.grades = grades;
341	        this.floor = sheet.getFloor();
342	        this.latePct = sheet.getLatePct();
343	        this.terms = sheet.getTerms();
344	        this.today = sheet.getToday();
345	    }
