353	     *  half to even; 0.00 when it is not overdue. */
354	    public BigDecimal lateCharge(Claim claim, BigDecimal figure) {
355	        if (figure == null || !overdue(claim)) {
356	            return BigDecimal.ZERO.setScale(2);
357	        }
358	        long periods = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today) / 30;
359	        return figure.multiply(latePct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
360	                .setScale(2, RoundingMode.HALF_EVEN);
361	    }
